"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9033],{57365:n=>{n.exports=JSON.parse('{"functions":[{"name":"ToDefinition","desc":"Turns a `Sound` and its `SoundEffect` children into a `SoundDefinition`. Only properties that differ from the\\ndefaults are kept, plus the name. Playback state (`Playing`, `TimePosition`) is never kept.\\n\\n```lua\\nlocal definition = VluxySF.Conversions.ToDefinition(workspace.MySound)\\n\\nprint(definition.Properties.Volume)\\n```","params":[{"name":"sound","desc":"The `Sound` to convert. Anything that is not a `Sound` warns and gives a blank definition.","lua_type":"Sound"}],"returns":[{"desc":"The definition.","lua_type":"SoundDefinition"}],"function_type":"static","source":{"line":34,"path":"lib/Api/Conversions.luau"}},{"name":"FromDefinition","desc":"Builds a new, unparented `Sound` from a `SoundDefinition`. Effects are parented under their class names. Each\\neffect carries its class name as `Name`. With no effects, pass an empty `Effects` table and an `EffectsCount` of 0.\\n\\n```lua\\nlocal sound = VluxySF.Conversions.FromDefinition({\\n\\tProperties = {\\n\\t\\tName = \\"MySound\\",\\n\\t\\tSoundId = \\"rbxassetid://123456789\\",\\n\\t\\tVolume = 0.5,\\n\\t},\\n\\tEffects = {\\n\\t\\tEchoSoundEffect = { Name = \\"EchoSoundEffect\\", Delay = 0.5 },\\n\\t},\\n\\tEffectsCount = 1,\\n})\\n\\nsound.Parent = workspace\\nsound:Play()\\n```\\n\\ngives a blank `Sound`.","params":[{"name":"definition","desc":"The definition to build. Anything without a `Properties` table warns and","lua_type":"SoundDefinition"}],"returns":[{"desc":"The new `Sound`.","lua_type":"Sound"}],"function_type":"static","source":{"line":74,"path":"lib/Api/Conversions.luau"}}],"properties":[],"types":[],"name":"Conversions","desc":"Converts between `Sounds` and `SoundDefinitions`. These do not need the schema, so they work before startup.\\n\\nNeither function throws on bad input: it warns and returns a blank definition or a silent blank `Sound` named\\n`VluxySF_Blank_Sound` instead.","source":{"line":16,"path":"lib/Api/Conversions.luau"}}')}}]);